    /// <para>Binds <c>SDL_CreateCursor</c>.</para>
    /// <para><c>mask</c> has to be in MSB (Most Significant Bit) format.</para>
    /// <para>The cursor width (<c>w</c>) must be a multiple of 8 bits.</para>
    /// <para>The cursor is created in black and white according to the following:</para>
    /// <list type="bullet">
    /// <item><description>data=0, mask=1: white</description></item>
    /// <item><description>data=1, mask=1: black</description></item>
    /// <item><description>data=0, mask=0: transparent</description></item>
    /// <item><description>data=1, mask=0: inverted color if possible, black if not.</description></item>
    /// </list>
    /// <para>Cursors created with this function must be freed with SDL_DestroyCursor().</para>
    /// <para>
    /// If you want to have a color cursor, or create your cursor from an SDL_Surface, you should use
    /// SDL_CreateColorCursor(). Alternately, you can hide the cursor and draw your own as part of your game's
    /// rendering, but it will be bound to the framerate.
    /// </para>
    /// <para>
    /// Also, SDL_CreateSystemCursor() is available, which provides several readily-available system cursors to pick
    /// from.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_CreateAnimatedCursor</c>, <c>SDL_CreateColorCursor</c>, <c>SDL_CreateSystemCursor</c>,
    /// <c>SDL_DestroyCursor</c>, <c>SDL_SetCursor</c>.
    /// </para>
    /// </remarks>
    /// <param name="data">the color value for each pixel of the cursor.</param>
    /// <param name="mask">the mask value for each pixel of the cursor.</param>
    /// <param name="w">the width of the cursor.</param>
    /// <param name="h">the height of the cursor.</param>
    /// <param name="hotX">
    /// the x-axis offset from the left of the cursor image to the mouse x position, in the range of 0 to <c>w</c> - 1.
    /// </param>
    /// <param name="hotY">
    /// the y-axis offset from the top of the cursor image to the mouse y position, in the range of 0 to <c>h</c> - 1.
    /// </param>
    /// <returns>
    /// a new cursor with the specified parameters on success or NULL on failure; call SDL_GetError() for more
    /// information.
    /// </returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_CreateCursor")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial Cursor CreateCursor(byte* data, byte* mask, int w, int h, int hotX, int hotY);

    /// <summary>Create a color cursor.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_CreateColorCursor</c>.</para>
    /// <para>
    /// If this function is passed a surface with alternate representations added with SDL_AddSurfaceAlternateImage(),
    /// the surface will be interpreted as the content to be used for 100% display scale, and the alternate
    /// representations will be used for high DPI situations if SDL_HINT_MOUSE_DPI_SCALE_CURSORS is enabled. For
    /// example, if the original surface is 32x32, then on a 2x macOS display or 200% display scale on Windows, a 64x64
    /// version of the image will be used, if available. If a matching version of the image isn't available, the closest
    /// larger size image will be downscaled to the appropriate size and be used instead, if available. Otherwise, the
    /// closest smaller image will be upscaled and be used instead.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_AddSurfaceAlternateImage</c>, <c>SDL_CreateAnimatedCursor</c>, <c>SDL_CreateCursor</c>,
    /// <c>SDL_CreateSystemCursor</c>, <c>SDL_DestroyCursor</c>, <c>SDL_SetCursor</c>.
    /// </para>
    /// </remarks>
    /// <param name="surface">an SDL_Surface structure representing the cursor image.</param>
    /// <param name="hotX">the x position of the cursor hot spot.</param>
    /// <param name="hotY">the y position of the cursor hot spot.</param>
    /// <returns>the new cursor on success or NULL on failure; call SDL_GetError() for more information.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_CreateColorCursor")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial Cursor CreateColorCursor(Surface* surface, int hotX, int hotY);

    /// <summary>Create an animated color cursor.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_CreateAnimatedCursor</c>.</para>
    /// <para>
    /// Animated cursors are composed of a sequential array of frames, specified as surfaces and durations in an array
    /// of SDL_CursorFrameInfo structs. The hot spot coordinates are universal to all frames, and all frames must have
    /// the same dimensions.
    /// </para>
    /// <para>
    /// Frame durations are specified in milliseconds. A duration of 0 implies an infinite frame time, and the animation
    /// will stop on that frame. To create a one-shot animation, set the duration of the last frame in the sequence to
    /// 0.
    /// </para>
    /// <para>
    /// If this function is passed surfaces with alternate representations added with SDL_AddSurfaceAlternateImage(),
    /// the surfaces will be interpreted as the content to be used for 100% display scale, and the alternate
    /// representations will be used for high DPI situations. For example, if the original surfaces are 32x32, then on a
    /// 2x macOS display or 200% display scale on Windows, a 64x64 version of the image will be used, if available. If a
    /// matching version of the image isn't available, the closest larger size image will be downscaled to the
    /// appropriate size and be used instead, if available. Otherwise, the closest smaller image will be upscaled and be
    /// used instead.
    /// </para>
    /// <para>
    /// If the underlying platform does not support animated cursors, this function will fall back to creating a static
    /// color cursor using the first frame in the sequence.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.4.0.</para>
    /// <para>
    /// See also: <c>SDL_AddSurfaceAlternateImage</c>, <c>SDL_CreateCursor</c>, <c>SDL_CreateColorCursor</c>,
    /// <c>SDL_CreateSystemCursor</c>, <c>SDL_DestroyCursor</c>, <c>SDL_SetCursor</c>.
    /// </para>
    /// </remarks>
    /// <param name="frames">an array of cursor images composing the animation.</param>
    /// <param name="frameCount">the number of frames in the sequence.</param>
    /// <param name="hotX">the x position of the cursor hot spot.</param>
    /// <param name="hotY">the y position of the cursor hot spot.</param>
    /// <returns>the new cursor on success or NULL on failure; call SDL_GetError() for more information.</returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_CreateAnimatedCursor")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial Cursor CreateAnimatedCursor(CursorFrameInfo* frames, int frameCount, int hotX, int hotY);

    /// <summary>Create an animated color cursor.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_CreateAnimatedCursor</c>.</para>
    /// <para>
    /// Animated cursors are composed of a sequential array of frames, specified as surfaces and durations in an array
    /// of SDL_CursorFrameInfo structs. The hot spot coordinates are universal to all frames, and all frames must have
    /// the same dimensions.
    /// </para>
    /// <para>
    /// Frame durations are specified in milliseconds. A duration of 0 implies an infinite frame time, and the animation
    /// will stop on that frame. To create a one-shot animation, set the duration of the last frame in the sequence to
    /// 0.
    /// </para>
    /// <para>
    /// If this function is passed surfaces with alternate representations added with SDL_AddSurfaceAlternateImage(),
    /// the surfaces will be interpreted as the content to be used for 100% display scale, and the alternate
    /// representations will be used for high DPI situations. For example, if the original surfaces are 32x32, then on a
    /// 2x macOS display or 200% display scale on Windows, a 64x64 version of the image will be used, if available. If a
    /// matching version of the image isn't available, the closest larger size image will be downscaled to the
    /// appropriate size and be used instead, if available. Otherwise, the closest smaller image will be upscaled and be
    /// used instead.
    /// </para>
    /// <para>
    /// If the underlying platform does not support animated cursors, this function will fall back to creating a static
    /// color cursor using the first frame in the sequence.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.4.0.</para>
    /// <para>
    /// See also: <c>SDL_AddSurfaceAlternateImage</c>, <c>SDL_CreateCursor</c>, <c>SDL_CreateColorCursor</c>,
    /// <c>SDL_CreateSystemCursor</c>, <c>SDL_DestroyCursor</c>, <c>SDL_SetCursor</c>.
    /// </para>
    /// </remarks>
    /// <param name="frames">an array of cursor images composing the animation.</param>
    /// <param name="hotX">the x position of the cursor hot spot.</param>
    /// <param name="hotY">the y position of the cursor hot spot.</param>
    /// <returns>the new cursor on success or NULL on failure; call SDL_GetError() for more information.</returns>
    public static Cursor CreateAnimatedCursor(Span<CursorFrameInfo> frames, int hotX, int hotY)
    {
        fixed (CursorFrameInfo* framesPtr = frames)
        {
            return CreateAnimatedCursor(framesPtr, frames.Length, hotX, hotY);
        }
    }

    /// <summary>Create a system cursor.</summary>
